const e=JSON.parse(`[{"unit":1,"dialogue":[{"who":"Nurse Chen","en":"Hi, I am Chen Mei. I am a nurse here.","zh":"嗨，我是陳美，我是這裡的護理師。"},{"who":"Amy","en":"Nice to meet you. I am Amy. I am a nursing student.","zh":"很高興認識你。我是 Amy，我是護理系學生。"},{"who":"Nurse Chen","en":"Are you nervous?","zh":"你緊張嗎？"},{"who":"Amy","en":"Yes, I am a little nervous.","zh":"是的，我有一點緊張。"},{"who":"Nurse Chen","en":"That is OK. The patients here are very nice.","zh":"沒關係，這裡的病人都很好。"},{"who":"Amy","en":"Is Mr. Lin in Room 5?","zh":"林先生在 5 號房嗎？"},{"who":"Nurse Chen","en":"Yes, he is. He is awake now, but he is tired.","zh":"對，他現在醒著，但是很累。"}],"questions":[{"q":"Who is Amy?","options":["A patient","A nurse","A nursing student"],"answer":2},{"q":"How is Mr. Lin?","options":["He is tired.","He is asleep.","He is hungry."],"answer":0}],"variations":[{"zh":"我不是醫生，我是護理師。","en":"I am not a doctor. I am a nurse."},{"zh":"你的病人很累嗎？","en":"Is your patient tired?"}],"cando":"用 am／is／are 介紹自己和別人，說出身分和狀態","scene":"實習第一天，在護理站","prompt":{"en":"Introduce yourself in three sentences: who you are, where you are now, and how you feel.","zh":"用三句英文介紹自己：你是誰、你現在在哪裡、你現在感覺怎麼樣（用 am／is／are）。","sample":"I am a nursing student in Taiwan. I am at home now. I am tired, but I am happy."}},{"unit":2,"dialogue":[{"who":"Nurse Chen","en":"Amy, this is an ice pack, and these are masks.","zh":"Amy，這是一個冰袋，這些是口罩。"},{"who":"Amy","en":"Are these gloves for the patients?","zh":"這些手套是給病人的嗎？"},{"who":"Nurse Chen","en":"No, they are for us. We need two boxes.","zh":"不是，是給我們用的。我們需要兩盒。"},{"who":"Amy","en":"OK. Is this towel for Mrs. Wang?","zh":"好。這條毛巾是給王太太的嗎？"},{"who":"Nurse Chen","en":"Yes. She has two children. They are in the room with her.","zh":"對。她有兩個小孩，他們跟她在房間裡。"},{"who":"Amy","en":"The children are so cute!","zh":"那兩個小孩好可愛！"}],"questions":[{"q":"Who are the gloves for?","options":["The patients","The children","The nurses"],"answer":2},{"q":"How many children does Mrs. Wang have?","options":["One","Three","Two"],"answer":2}],"variations":[{"zh":"我需要一條毛巾和兩個口罩。","en":"I need a towel and two masks."},{"zh":"這是一顆雞蛋，不是一顆蘋果。","en":"This is an egg, not an apple."}],"cando":"用 a／an 和複數說出身邊的東西，例如病房裡的用品","scene":"準備病房用品","prompt":{"en":"Look around your room. Name three things you see. Use a, an, or plural -s.","zh":"看看你的房間，用英文說三樣你看到的東西，要用到 a、an 或複數 -s。","sample":"I see a bed, an umbrella, and two books."}},{"unit":3,"dialogue":[{"who":"Nurse Chen","en":"Mr. Lin, here is a cup of water and a pill.","zh":"林先生，這裡有一杯水和一顆藥。"},{"who":"Mr. Lin","en":"Is the pill for my pain?","zh":"這顆藥是治我的疼痛的嗎？"},{"who":"Nurse Chen","en":"Yes, it is. The water is warm.","zh":"是的。這杯水是溫的。"},{"who":"Mr. Lin","en":"Thank you. Is the door open? The room is cold.","zh":"謝謝。門是開著的嗎？房間很冷。"},{"who":"Nurse Chen","en":"Yes, it is. I am sorry. Now the door is closed.","zh":"對，抱歉。現在門關上了。"}],"questions":[{"q":"What is the pill for?","options":["His cough","His sleep","His pain"],"answer":2},{"q":"Why is the room cold?","options":["The water is cold.","The door is open.","The window is broken."],"answer":1}],"variations":[{"zh":"這是一本書，這本書很新。","en":"This is a book. The book is new."},{"zh":"我有一個朋友和一隻貓，那隻貓很胖。","en":"I have a friend and a cat. The cat is fat."}],"cando":"第一次提到用 a／an，再提到或雙方都知道是哪個時用 the","scene":"給病人送藥和水","prompt":{"en":"Name one thing in your room with a or an. Then say one more sentence about it with the.","zh":"先用 a／an 說你房間裡的一樣東西，再用 the 多說一句。","sample":"I have a desk. The desk is old, but it is clean."}},{"unit":4,"dialogue":[{"who":"Amy","en":"I get up at six every day.","zh":"我每天六點起床。"},{"who":"Ben","en":"Really? I get up at eight. My sister gets up at six too.","zh":"真的嗎？我八點起床。我姊姊也是六點起床。"},{"who":"Amy","en":"She is a nurse, right?","zh":"她是護理師，對吧？"},{"who":"Ben","en":"Yes. She works at a hospital. She takes the bus to work.","zh":"對。她在醫院工作，她搭公車上班。"},{"who":"Amy","en":"I walk to school. It takes twenty minutes.","zh":"我走路上學，要二十分鐘。"},{"who":"Ben","en":"My sister has a busy job. She takes care of many patients every day.","zh":"我姊姊的工作很忙，她每天要照顧很多病人。"}],"questions":[{"q":"When does Ben's sister get up?","options":["At eight","At six","At seven"],"answer":1},{"q":"How does Ben's sister go to work?","options":["On foot","By car","By bus"],"answer":2}],"variations":[{"zh":"我媽媽每天早上喝咖啡。","en":"My mother drinks coffee every morning."},{"zh":"他每天晚上讀書。","en":"He studies every night."}],"cando":"用現在簡單式說自己和別人每天的習慣（he／she 的動詞加 -s）","scene":"同學聊每天的作息","prompt":{"en":"Write three things you do every day, and one thing a family member does every day.","zh":"寫三件你每天做的事，再寫一件家人每天做的事（he／she 的動詞記得加 -s）。","sample":"I get up at seven. I take the bus to school. I study English at night. My mom cooks dinner every day."}},{"unit":5,"dialogue":[{"who":"Nurse Chen","en":"Do you drink coffee, Mr. Lin?","zh":"林先生，你喝咖啡嗎？"},{"who":"Mr. Lin","en":"No, I don't. I drink tea.","zh":"不，我不喝。我喝茶。"},{"who":"Nurse Chen","en":"Do you smoke?","zh":"你抽菸嗎？"},{"who":"Mr. Lin","en":"No, I don't. But my son smokes.","zh":"不，我不抽。但是我兒子抽。"},{"who":"Nurse Chen","en":"Does your wife cook for you?","zh":"你太太會幫你煮飯嗎？"},{"who":"Mr. Lin","en":"Yes, she does. She doesn't put salt in my food.","zh":"會。她不在我的飯菜裡放鹽。"}],"questions":[{"q":"What does Mr. Lin drink?","options":["Milk","Tea","Coffee"],"answer":1},{"q":"Who smokes?","options":["Mr. Lin's wife","Mr. Lin","Mr. Lin's son"],"answer":2}],"variations":[{"zh":"你每天運動嗎？","en":"Do you exercise every day?"},{"zh":"她不喝牛奶。","en":"She doesn't drink milk."}],"cando":"用 Do／Does 問別人的習慣，用 don't／doesn't 說沒有","scene":"護理師問病人的生活習慣","prompt":{"en":"Write two Do you…? questions for a new patient about their habits. Then answer them for yourself.","zh":"寫兩個用 Do you…? 問新病人生活習慣的問題，再用自己的情況回答。","sample":"Do you drink coffee? Yes, I do. Do you smoke? No, I don't."}},{"unit":6,"dialogue":[{"who":"Senior nurse","en":"Amy, what are you doing now?","zh":"Amy，你現在在做什麼？"},{"who":"Amy","en":"I am checking Mrs. Wang's blood pressure.","zh":"我在幫王太太量血壓。"},{"who":"Senior nurse","en":"Is Mr. Lin sleeping?","zh":"林先生在睡覺嗎？"},{"who":"Amy","en":"No, he is not. He is eating lunch.","zh":"沒有，他在吃午餐。"},{"who":"Senior nurse","en":"Are his children visiting?","zh":"他的孩子在探病嗎？"},{"who":"Amy","en":"Yes. They are sitting by his bed and talking.","zh":"對。他們坐在他床邊聊天。"}],"questions":[{"q":"What is Amy doing?","options":["Sleeping","Eating lunch","Checking blood pressure"],"answer":2},{"q":"What is Mr. Lin doing?","options":["Talking on the phone","Sleeping","Eating lunch"],"answer":2}],"variations":[{"zh":"我現在正在等醫生。","en":"I am waiting for the doctor now."},{"zh":"他們沒有在看電視。","en":"They are not watching TV."}],"cando":"用 am／is／are ＋ -ing 說現在正在做的事","scene":"學姊打電話問病房現在的情況","prompt":{"en":"Look around you, or imagine a hospital room. Write three sentences about what people are doing right now.","zh":"看看你周圍（或想像一間病房），寫三句「現在正在做什麼」。","sample":"I am sitting at my desk. My brother is playing games. My mom is cooking dinner."}},{"unit":7,"dialogue":[{"who":"Nurse A","en":"How was Mr. Lin last night?","zh":"林先生昨晚怎麼樣？"},{"who":"Nurse B","en":"He was in pain at midnight.","zh":"他半夜很痛。"},{"who":"Nurse A","en":"Were his children here?","zh":"他的孩子有在這裡嗎？"},{"who":"Nurse B","en":"No, they were not. They were at home.","zh":"沒有，他們在家。"},{"who":"Nurse A","en":"Was he hungry this morning?","zh":"他今天早上有餓嗎？"},{"who":"Nurse B","en":"Yes, he was. He is better now.","zh":"有。他現在好多了。"}],"questions":[{"q":"When was Mr. Lin in pain?","options":["At midnight","Right now","This morning"],"answer":0},{"q":"Where were his children last night?","options":["At the hospital","At home","At school"],"answer":1}],"variations":[{"zh":"我昨天很忙。","en":"I was busy yesterday."},{"zh":"你們上週在台北嗎？","en":"Were you in Taipei last week?"}],"cando":"用 was／were 說昨天或剛才的狀態","scene":"交班時談昨晚的病人","prompt":{"en":"Write three sentences about yesterday: where you were, who you were with, and how you felt.","zh":"寫三句昨天的事：你在哪裡、跟誰在一起、感覺怎麼樣（用 was／were）。","sample":"I was at school yesterday. I was with my classmates. We were tired after class."}},{"unit":8,"dialogue":[{"who":"Nurse Chen","en":"Good morning, Mrs. Wang. How was yesterday?","zh":"王太太早安，昨天還好嗎？"},{"who":"Mrs. Wang","en":"It was good. I walked in the hallway twice.","zh":"很好。我在走廊走了兩次。"},{"who":"Nurse Chen","en":"Great. Your daughter visited you, right?","zh":"很好。你女兒來看過你，對吧？"},{"who":"Mrs. Wang","en":"Yes. She stayed for two hours. We talked and watched TV.","zh":"對，她待了兩個小時。我們聊天、看電視。"},{"who":"Nurse Chen","en":"Your son called too?","zh":"你兒子也有打電話來？"},{"who":"Mrs. Wang","en":"Yes, he called at night. He wanted to know how I was.","zh":"有，他晚上打來，想知道我好不好。"}],"questions":[{"q":"How many times did Mrs. Wang walk in the hallway?","options":["Three times","Once","Twice"],"answer":2},{"q":"How long did her daughter stay?","options":["Two hours","All day","One hour"],"answer":0}],"variations":[{"zh":"我昨天晚上打掃了房間。","en":"I cleaned my room last night."},{"zh":"他們上週末在家看了電影。","en":"They watched a movie at home last weekend."}],"cando":"用規則動詞 -ed 說昨天做了什麼","scene":"病人說昨天過得怎麼樣","prompt":{"en":"Write three things you did yesterday. Use verbs with -ed, like walked, cooked, or studied.","zh":"寫三件你昨天做的事，用加 -ed 的動詞。","sample":"I walked to school. I studied English after dinner. I washed the dishes."}},{"unit":9,"dialogue":[{"who":"Nurse Chen","en":"Mr. Chen, what happened last night?","zh":"陳先生，昨晚發生了什麼事？"},{"who":"Mr. Chen","en":"I got up at two and went to the bathroom.","zh":"我兩點起床去廁所。"},{"who":"Nurse Chen","en":"And then?","zh":"然後呢？"},{"who":"Mr. Chen","en":"I felt dizzy and fell down.","zh":"我覺得頭暈，然後就跌倒了。"},{"who":"Nurse Chen","en":"Oh no. You hurt your knee.","zh":"哎呀，你傷到膝蓋了。"},{"who":"Mr. Chen","en":"Yes. My son came and took me back to bed.","zh":"對，我兒子過來扶我回床上。"}],"questions":[{"q":"How did Mr. Chen feel before he fell?","options":["He felt hungry.","He felt dizzy.","He felt cold."],"answer":1},{"q":"Who took him back to bed?","options":["A nurse","His wife","His son"],"answer":2}],"variations":[{"zh":"我今天早上喝了一杯牛奶。","en":"I drank a glass of milk this morning."},{"zh":"她昨天看到那位醫生了。","en":"She saw the doctor yesterday."}],"cando":"用常見的不規則過去式說發生過的事","scene":"病人說昨晚怎麼跌倒的","prompt":{"en":"Write about last weekend in three sentences. Use at least two of these: went, ate, saw, had, took.","zh":"用三句寫上週末，至少用到兩個：went、ate、saw、had、took。","sample":"I went to Taichung last weekend. I ate beef noodles with my family. We had a good time."}},{"unit":10,"dialogue":[{"who":"Nurse Chen","en":"Good morning. Did you sleep well last night?","zh":"早安，你昨晚睡得好嗎？"},{"who":"Mrs. Lee","en":"No, I didn't. My back hurt.","zh":"不好，我背痛。"},{"who":"Nurse Chen","en":"Did you take your pain medicine?","zh":"你有吃止痛藥嗎？"},{"who":"Mrs. Lee","en":"Yes, I did. But it didn't help.","zh":"有，但是沒有用。"},{"who":"Nurse Chen","en":"Did you eat breakfast?","zh":"你吃早餐了嗎？"},{"who":"Mrs. Lee","en":"No. I didn't feel hungry.","zh":"沒有，我不覺得餓。"}],"questions":[{"q":"Why didn't Mrs. Lee sleep well?","options":["She was hungry.","Her back hurt.","The room was noisy."],"answer":1},{"q":"Did the pain medicine help?","options":["Yes, it helped a lot.","No, it didn't.","She didn't take it."],"answer":1}],"variations":[{"zh":"你昨天有去上課嗎？","en":"Did you go to class yesterday?"},{"zh":"他沒有打電話給我。","en":"He didn't call me."}],"cando":"用 Did…? 問過去的事，用 didn't 說沒做（後面動詞回原形）","scene":"早上確認病人睡得好不好、有沒有吃藥","prompt":{"en":"Write two Did…? questions you can ask a patient in the morning, and a short answer to each.","zh":"寫兩個早上可以問病人的 Did…? 問句，各配一個簡短回答。","sample":"Did you sleep well? No, I didn't. Did you eat breakfast? Yes, I did."}},{"unit":11,"dialogue":[{"who":"Nurse Chen","en":"Mr. Lin, you will have a blood test tomorrow morning.","zh":"林先生，你明天早上要抽血檢查。"},{"who":"Mr. Lin","en":"Will it hurt?","zh":"會痛嗎？"},{"who":"Nurse Chen","en":"It will hurt a little, but it will be quick.","zh":"會有一點痛，但是很快。"},{"who":"Mr. Lin","en":"What about breakfast?","zh":"那早餐呢？"},{"who":"Nurse Chen","en":"This test needs an empty stomach, so you will eat after the test.","zh":"這項檢查要空腹，所以你檢查完再吃。"},{"who":"Mr. Lin","en":"OK. My daughter is going to come at nine.","zh":"好。我女兒九點會來。"}],"questions":[{"q":"When will Mr. Lin have the blood test?","options":["Tonight","Next week","Tomorrow morning"],"answer":2},{"q":"When will he eat breakfast?","options":["After the test","Before the test","At nine"],"answer":0}],"variations":[{"zh":"我明天會早一點來。","en":"I will come early tomorrow.","alt":["I'll come early tomorrow.","I will come earlier tomorrow.","I'll come earlier tomorrow."]},{"zh":"我們下週要去看醫生。","en":"We are going to see the doctor next week."}],"cando":"用 will／be going to 說之後的安排和計畫","scene":"護理師說明明天的抽血檢查","prompt":{"en":"Write three plans for this weekend. Use will or be going to.","zh":"寫三個這週末的計畫，用 will 或 be going to。","sample":"I am going to clean my room. I will study for my test. I will call my grandma."}},{"unit":12,"dialogue":[{"who":"Mr. Lin","en":"Can I take a shower today?","zh":"我今天可以洗澡嗎？"},{"who":"Nurse Chen","en":"No, you can't. Your wound must stay dry.","zh":"不行，你的傷口必須保持乾燥。"},{"who":"Mr. Lin","en":"Can I walk?","zh":"我可以走路嗎？"},{"who":"Nurse Chen","en":"Yes, you can. You should walk a little every day.","zh":"可以，你應該每天走一點路。"},{"who":"Mr. Lin","en":"May I drink coffee?","zh":"我可以喝咖啡嗎？"},{"who":"Nurse Chen","en":"You should not drink coffee this week. Drink water.","zh":"這週你最好不要喝咖啡，喝水吧。"}],"questions":[{"q":"Why can't Mr. Lin take a shower?","options":["The water is cold.","He is too tired.","His wound must stay dry."],"answer":2},{"q":"What should he do every day?","options":["Take a shower","Walk a little","Drink coffee"],"answer":1}],"variations":[{"zh":"你應該早點睡。","en":"You should go to bed early."},{"zh":"我不會游泳。","en":"I can't swim."}],"cando":"用 can／should／must 說能不能、該不該、一定要（衛教用語）","scene":"術後衛教：能不能洗澡、走路","prompt":{"en":"A friend has a cold. Give three pieces of advice with should or should not.","zh":"朋友感冒了，用 should／should not 給三個建議。","sample":"You should drink more water. You should rest at home. You should not stay up late."}},{"unit":13,"dialogue":[{"who":"Clinic","en":"Hello, this is City Clinic.","zh":"你好，這裡是市立診所。"},{"who":"Amy","en":"Hi. Is my appointment on Monday?","zh":"你好，請問我的預約是星期一嗎？"},{"who":"Clinic","en":"No, it is on Tuesday, at ten in the morning.","zh":"不是，是星期二早上十點。"},{"who":"Amy","en":"Is the clinic on the second floor?","zh":"診所在二樓嗎？"},{"who":"Clinic","en":"Yes. Please be at the front desk at nine fifty.","zh":"對。請九點五十到櫃檯。"},{"who":"Amy","en":"OK. I am busy in the afternoon, so the morning is good.","zh":"好，我下午很忙，所以早上剛好。"}],"questions":[{"q":"When is Amy's appointment?","options":["Tuesday at 10 a.m.","Tuesday at 2 p.m.","Monday at 10 a.m."],"answer":0},{"q":"Where is the clinic?","options":["On the first floor","On the second floor","Next to the school"],"answer":1}],"variations":[{"zh":"我的生日在七月。","en":"My birthday is in July."},{"zh":"我們星期五晚上在餐廳見面。","en":"We will meet at the restaurant on Friday night."}],"cando":"用 at／on／in 說清楚時間和地點（約診、上課）","scene":"打電話確認門診時間","prompt":{"en":"Write your schedule for tomorrow in three sentences. Use at, on, and in.","zh":"用三句寫你明天的行程，要用到 at、on、in。","sample":"I have class at eight in the morning. My class is in Room 302 on the third floor. I will be at home in the evening."}},{"unit":14,"dialogue":[{"who":"Dietitian","en":"How much water do you drink every day?","zh":"你每天喝多少水？"},{"who":"Mr. Lin","en":"Not much. Maybe two cups.","zh":"不多，大概兩杯。"},{"who":"Dietitian","en":"How many meals do you eat?","zh":"你一天吃幾餐？"},{"who":"Mr. Lin","en":"Two. I don't have time for breakfast.","zh":"兩餐，我沒時間吃早餐。"},{"who":"Dietitian","en":"Do you eat any fruit?","zh":"你有吃水果嗎？"},{"who":"Mr. Lin","en":"A little. I eat a few apples every week.","zh":"一點點，我每週吃幾顆蘋果。"}],"questions":[{"q":"How much water does Mr. Lin drink?","options":["About two cups","No water","About eight cups"],"answer":0},{"q":"How many meals does he eat a day?","options":["One","Three","Two"],"answer":2}],"variations":[{"zh":"我沒有很多時間。","en":"I don't have much time."},{"zh":"他吃了很多餅乾。","en":"He ate a lot of cookies."}],"cando":"用 many／much／a few／a little／some／any 說數量","scene":"營養師問飲食","prompt":{"en":"Write about what you ate and drank yesterday. Use much, many, a few, or a little.","zh":"寫你昨天吃了什麼、喝了什麼，用 much、many、a few 或 a little。","sample":"I drank a lot of water yesterday. I ate a few cookies. I did not eat much rice."}},{"unit":15,"dialogue":[{"who":"Nurse Chen","en":"How are you today, Mr. Lin? Is the pain better?","zh":"林先生今天如何？疼痛好一點了嗎？"},{"who":"Mr. Lin","en":"Yes, it is better than yesterday.","zh":"好多了，比昨天好。"},{"who":"Nurse Chen","en":"Good. Is this bed more comfortable than the old one?","zh":"很好。這張床比舊的舒服嗎？"},{"who":"Mr. Lin","en":"Yes, much more comfortable. But this room is colder.","zh":"對，舒服多了。但這個房間比較冷。"},{"who":"Nurse Chen","en":"Here. This is the warmest blanket we have.","zh":"來，這是我們最暖的毯子。"},{"who":"Mr. Lin","en":"Thank you. You are the nicest nurse here.","zh":"謝謝，你是這裡最好的護理師。"}],"questions":[{"q":"How is Mr. Lin's pain today?","options":["Better than yesterday","Worse than yesterday","The same as yesterday"],"answer":0},{"q":"What is the problem with the new room?","options":["It is noisier.","It is colder.","It is smaller."],"answer":1}],"variations":[{"zh":"我的房間比你的小。","en":"My room is smaller than yours."},{"zh":"這是最貴的藥。","en":"This is the most expensive medicine."}],"cando":"用比較級和最高級比較兩樣東西、說出「最…」","scene":"病人比較今天和昨天的狀況","prompt":{"en":"Compare two people or two places you know. Then use a superlative to say that one of them is the most … in a bigger group (your family, your class, Taiwan…).","zh":"比較兩個你認識的人或地方，再用最高級說其中一個在更大的範圍裡「最…」（全家、全班、全台灣……）。","sample":"My sister is taller than I am. I am more patient than she is. She is the tallest person in our family."}},{"unit":16,"dialogue":[{"who":"Nurse Chen","en":"What is your name, please?","zh":"請問你叫什麼名字？"},{"who":"Mrs. Chen","en":"My name is Chen Hua.","zh":"我叫陳華。"},{"who":"Nurse Chen","en":"Where does it hurt?","zh":"哪裡痛？"},{"who":"Mrs. Chen","en":"My stomach. It hurts here.","zh":"胃，這裡痛。"},{"who":"Nurse Chen","en":"When did the pain start?","zh":"什麼時候開始痛的？"},{"who":"Mrs. Chen","en":"Last night, after dinner.","zh":"昨晚，吃完晚餐以後。"},{"who":"Nurse Chen","en":"Who came with you today?","zh":"今天誰陪你來的？"},{"who":"Mrs. Chen","en":"My husband. He is outside.","zh":"我先生，他在外面。"}],"questions":[{"q":"Where is the pain?","options":["In her back","In her head","In her stomach"],"answer":2},{"q":"When did the pain start?","options":["Last night after dinner","This morning","Two days ago"],"answer":0}],"variations":[{"zh":"你為什麼遲到？","en":"Why are you late?"},{"zh":"你是怎麼來醫院的？","en":"How did you come to the hospital?"}],"cando":"用 What／Where／When／Who／How 問病人的基本資料和症狀","scene":"入院問診","prompt":{"en":"Write four questions you can ask a new patient. Use four different question words.","zh":"寫四個可以問新病人的問題，用四個不同的疑問詞。","sample":"What is your name? Where do you live? When did the pain start? Who is your emergency contact?"}},{"unit":17,"dialogue":[{"who":"Ben","en":"You look tired. Are you OK?","zh":"你看起來好累，還好嗎？"},{"who":"Amy","en":"I am tired because I studied until two.","zh":"我很累，因為我讀書讀到兩點。"},{"who":"Ben","en":"We have a test today, so you studied late?","zh":"我們今天有考試，所以你讀到很晚？"},{"who":"Amy","en":"Yes. The test is hard, but I am ready.","zh":"對。考試很難，但是我準備好了。"},{"who":"Ben","en":"I didn't study much, so I am worried.","zh":"我沒讀多少，所以很擔心。"},{"who":"Amy","en":"Let's study together at lunch, and we can eat too.","zh":"我們午餐時一起讀吧，還可以順便吃飯。"}],"questions":[{"q":"Why is Amy tired?","options":["She worked all night.","She studied until two.","She was sick."],"answer":1},{"q":"Why is Ben worried?","options":["He is late.","He is sick.","He didn't study much."],"answer":2}],"variations":[{"zh":"外面在下雨，所以我待在家。","en":"It is raining, so I am staying home."},{"zh":"我想睡覺，但是我還有功課。","en":"I want to sleep, but I still have homework."}],"cando":"用 and／but／so／because 把兩件事接成一句","scene":"考試前同學聊天","prompt":{"en":"Write three sentences about your day. Use three of these: and, but, so, because.","zh":"寫三句今天的事，用到 and、but、so、because 其中三個。","sample":"I was busy today, but I went to the gym. I was hungry after that, so I ate a big dinner. I am tired now because I walked a lot."}},{"unit":18,"dialogue":[{"who":"Nurse Chen","en":"Take this medicine after breakfast and after dinner.","zh":"這個藥早餐後和晚餐後吃。"},{"who":"Mr. Lin","en":"What if I forget?","zh":"如果我忘了怎麼辦？"},{"who":"Nurse Chen","en":"If you forget a dose, read the instructions for this medicine or ask the pharmacist.","zh":"如果忘了吃一次，看這個藥的用藥說明，或問藥師該怎麼做。"},{"who":"Mr. Lin","en":"Should I wash my hands before I change the dressing?","zh":"換藥前要先洗手嗎？"},{"who":"Nurse Chen","en":"Yes. Always wash your hands before you touch the wound.","zh":"要，碰傷口之前一定要先洗手。"},{"who":"Mr. Lin","en":"OK. I will call you if the wound gets red.","zh":"好，如果傷口變紅，我會打電話給你。"}],"questions":[{"q":"When should Mr. Lin take the medicine?","options":["Before bed","Before breakfast","After breakfast and after dinner"],"answer":2},{"q":"What should he do before he touches the wound?","options":["Wash his hands","Take the medicine","Call the nurse"],"answer":0}],"variations":[{"zh":"我到家以後會傳訊息給你。","en":"I will text you after I get home."},{"zh":"如果明天下雨，我們就不去了。","en":"If it rains tomorrow, we will not go."}],"cando":"用 when／before／after／if 說明步驟和條件（衛教）","scene":"出院衛教：吃藥和換藥","prompt":{"en":"Write three sentences about how you take care of yourself when you have a cold. Use when, before, after, or if.","zh":"用三句說明你感冒時怎麼照顧自己，用到 when、before、after 或 if。","sample":"When I have a cold, I drink a lot of water. I take medicine after I eat. If I have a fever, I see a doctor."}},{"unit":19,"dialogue":[{"who":"Nurse Chen","en":"How long have you had this cough?","zh":"你咳嗽多久了？"},{"who":"Mr. Lin","en":"I have had it for two weeks.","zh":"兩個禮拜了。"},{"who":"Nurse Chen","en":"Have you seen a doctor?","zh":"你看過醫生了嗎？"},{"who":"Mr. Lin","en":"No, I haven't. I have taken some cough syrup.","zh":"還沒，我吃過一些咳嗽糖漿。"},{"who":"Nurse Chen","en":"Has your fever gone down?","zh":"你的燒退了嗎？"},{"who":"Mr. Lin","en":"Yes. I haven't had a fever since Sunday.","zh":"退了，從星期天就沒發燒了。"}],"questions":[{"q":"How long has Mr. Lin had the cough?","options":["Since Sunday","Two weeks","Two days"],"answer":1},{"q":"What has he taken?","options":["Antibiotics","Nothing","Cough syrup"],"answer":2}],"variations":[{"zh":"我去過日本兩次。","en":"I have been to Japan twice."},{"zh":"她在這家醫院工作十年了。","en":"She has worked at this hospital for ten years."}],"cando":"用 have／has ＋ 過去分詞說經驗和持續多久（for／since）","scene":"問診：咳嗽多久了","prompt":{"en":"Write three sentences: something you have done, something you have never done, and how long you have studied nursing.","zh":"寫三句：一件你做過的事、一件你從沒做過的事、你讀護理多久了。","sample":"I have been to Kaohsiung. I have never been on a plane. I have studied nursing for two years."}},{"unit":20,"dialogue":[{"who":"Nurse A","en":"Mr. Wang came in two days ago.","zh":"王先生兩天前入院。"},{"who":"Nurse A","en":"He has had a fever since yesterday.","zh":"他從昨天開始發燒。"},{"who":"Nurse B","en":"When did the fever start?","zh":"發燒是什麼時候開始的？"},{"who":"Nurse A","en":"It started at six last night.","zh":"昨晚六點開始的。"},{"who":"Nurse B","en":"Has he eaten anything today?","zh":"他今天吃過東西了嗎？"},{"who":"Nurse A","en":"Yes. He ate some porridge at nine.","zh":"吃了，他九點吃了一些粥。"}],"questions":[{"q":"When did Mr. Wang come in?","options":["Yesterday","Two days ago","Last week"],"answer":1},{"q":"What did he eat at nine?","options":["Nothing","Some porridge","Some bread"],"answer":1}],"variations":[{"zh":"我已經吃過午餐了。","en":"I have already had lunch."},{"zh":"他上個月去了花蓮。","en":"He went to Hualien last month."}],"cando":"有明確過去時間用過去式，從以前延續到現在用現在完成式","scene":"交班報告：入院經過","prompt":{"en":"Say something you have done (no time). Then add when you did it, in the past tense.","zh":"先用現在完成式說一件你做過的事，再用過去式說是什麼時候做的。","sample":"I have been to Kenting. I went there last summer with my family."}},{"unit":21,"dialogue":[{"who":"Nurse A","en":"Was Mrs. Lee's medicine given?","zh":"李太太的藥給了嗎？"},{"who":"Nurse B","en":"Yes. It was given at eight.","zh":"給了，八點給的。"},{"who":"Nurse A","en":"Was her blood taken this morning?","zh":"她今天早上抽血了嗎？"},{"who":"Nurse B","en":"Yes. The blood was sent to the lab.","zh":"抽了，血已經送到檢驗室。"},{"who":"Nurse A","en":"Good. Her room is cleaned every day, right?","zh":"很好。她的房間每天都會打掃，對吧？"},{"who":"Nurse B","en":"Yes. It was cleaned an hour ago.","zh":"對，一小時前剛打掃過。"}],"questions":[{"q":"When was the medicine given?","options":["An hour ago","At eight","At nine"],"answer":1},{"q":"Where was the blood sent?","options":["To the lab","To the doctor","To the pharmacy"],"answer":0}],"variations":[{"zh":"這間醫院是 1990 年蓋的。","en":"This hospital was built in 1990."},{"zh":"很多國家都說英文。","en":"English is spoken in many countries."}],"cando":"用 be ＋ 過去分詞說「被做」的事（處置、紀錄）","scene":"口頭交班：藥和檢驗","prompt":{"en":"Write three passive sentences about your school or a hospital: something done every day and something done yesterday.","zh":"用被動寫三句學校或醫院的事：每天被做的事、昨天被做的事。","sample":"The classroom is cleaned every day. The test was given yesterday. Our homework was checked by the teacher."}},{"unit":22,"dialogue":[{"who":"Mr. Lin","en":"I want to go home today.","zh":"我今天想回家。"},{"who":"Nurse Chen","en":"I know. But you need to rest one more day.","zh":"我知道，但你需要再休息一天。"},{"who":"Mr. Lin","en":"I enjoy talking with you, but I miss my dog.","zh":"我喜歡跟你聊天，但我想念我的狗。"},{"who":"Nurse Chen","en":"Do you plan to walk your dog every day?","zh":"你打算每天遛狗嗎？"},{"who":"Mr. Lin","en":"Yes. I love walking with him. And I will stop smoking.","zh":"對，我很喜歡跟牠散步。還有，我會戒菸。"},{"who":"Nurse Chen","en":"Great. Quitting smoking is good for your heart.","zh":"太好了，戒菸對你的心臟很好。"}],"questions":[{"q":"What does Mr. Lin want to do?","options":["Go home","Walk in the hallway","Eat dinner"],"answer":0},{"q":"What will Mr. Lin stop doing?","options":["Walking","Smoking","Talking"],"answer":1}],"variations":[{"zh":"我決定學日文。","en":"I decided to learn Japanese."},{"zh":"你介意等一下嗎？","en":"Do you mind waiting?"}],"cando":"分得出 want／need／plan to ＋ 原形，和 enjoy／finish／stop ＋ -ing","scene":"病人想出院","prompt":{"en":"Write one thing you enjoy doing, one thing you want to do this year, and one thing you need to stop doing.","zh":"寫：一件你喜歡做的事（enjoy -ing）、一件今年想做的事（want to）、一件該停止的事（stop -ing）。","sample":"I enjoy listening to music. I want to pass the English test this year. I need to stop staying up late."}},{"unit":23,"dialogue":[{"who":"Nurse Chen","en":"There is a call button next to your bed.","zh":"你床邊有一個呼叫鈴。"},{"who":"Mrs. Wang","en":"Is there a bathroom in this room?","zh":"這間房裡有廁所嗎？"},{"who":"Nurse Chen","en":"Yes, there is. There are two towels in it.","zh":"有，裡面有兩條毛巾。"},{"who":"Mrs. Wang","en":"Are there any shops near here?","zh":"附近有商店嗎？"},{"who":"Nurse Chen","en":"There is a convenience store on the first floor.","zh":"一樓有一間便利商店。"},{"who":"Nurse Chen","en":"It is important to press the button if you need help.","zh":"需要幫忙時記得按鈴，這很重要。"}],"questions":[{"q":"Where is the call button?","options":["In the bathroom","On the door","Next to the bed"],"answer":2},{"q":"Where is the convenience store?","options":["Across the street","On the second floor","On the first floor"],"answer":2}],"variations":[{"zh":"冰箱裡有一些蘋果。","en":"There are some apples in the fridge."},{"zh":"早點睡很重要。","en":"It is important to go to bed early."}],"cando":"用 There is／There are 說某處有什麼，用 It is … to … 說看法","scene":"帶新病人認識病房","prompt":{"en":"Describe your room or your classroom in three sentences with there is or there are.","zh":"用 there is／there are 寫三句描述你的房間或教室。","sample":"There is a bed by the window. There are many books on my desk. There is a small plant next to the door."}},{"unit":24,"dialogue":[{"who":"Nurse Chen","en":"How often do you take your blood pressure pill?","zh":"你的血壓藥多久吃一次？"},{"who":"Mrs. Wang","en":"Once a day, in the morning.","zh":"一天一次，早上吃。"},{"who":"Nurse Chen","en":"Do you ever forget?","zh":"你會忘記嗎？"},{"who":"Mrs. Wang","en":"Sometimes. I usually remember, but I never take it at night.","zh":"有時候。我通常記得，但我從不在晚上吃。"},{"who":"Nurse Chen","en":"How often do you exercise?","zh":"你多久運動一次？"},{"who":"Mrs. Wang","en":"Twice a week. I always walk in the park.","zh":"一週兩次，我都在公園走路。"}],"questions":[{"q":"How often does Mrs. Wang take the pill?","options":["Twice a week","Once a day","Twice a day"],"answer":1},{"q":"How often does she exercise?","options":["Never","Twice a week","Every day"],"answer":1}],"variations":[{"zh":"我從來不在早上喝咖啡。","en":"I never drink coffee in the morning."},{"zh":"這個藥一天吃三次。","en":"Take this medicine three times a day."}],"cando":"用 always／usually／sometimes／never 和 once／twice a day 說頻率","scene":"問病人吃藥和運動的頻率","prompt":{"en":"Write about your week: two things you always or usually do, and one thing you never do. Add how often (twice a week, every day…) to at least one of them.","zh":"寫你的一週：兩件總是或通常做的事、一件從來不做的事；至少一句加上次數（once a week、every day…），其他句可以只說時間。","sample":"I usually get up at seven. I go to the gym twice a week. I never skip breakfast."}},{"unit":25,"dialogue":[{"who":"Nurse Chen","en":"Good morning. Please sit down here.","zh":"早安，請坐這裡。"},{"who":"Nurse Chen","en":"Could you roll up your sleeve?","zh":"可以請你把袖子捲起來嗎？"},{"who":"Mr. Lin","en":"Sure. Like this?","zh":"好，這樣嗎？"},{"who":"Nurse Chen","en":"Yes. Please relax your arm, and don't move.","zh":"對，請放鬆手臂，不要動。"},{"who":"Nurse Chen","en":"OK, all done. Could you hold this gauze here and keep your arm straight?","zh":"好了。可以請你用這塊紗布壓著這裡，手臂伸直嗎？"},{"who":"Mr. Lin","en":"Sure. Can I go now?","zh":"好。我可以走了嗎？"},{"who":"Nurse Chen","en":"Not yet. I will check that the bleeding has stopped first.","zh":"還不行，我要先確認已經不流血了。"}],"questions":[{"q":"What does the nurse ask Mr. Lin to do first?","options":["Lie down","Stand up","Sit down"],"answer":2},{"q":"What will the nurse check before Mr. Lin goes?","options":["His temperature","His sleeve","That the bleeding has stopped"],"answer":2}],"variations":[{"zh":"請不要在這裡吃東西。","en":"Please do not eat here."},{"zh":"可以請你說慢一點嗎？","en":"Could you speak more slowly?"}],"cando":"用祈使句和 Could you…? 有禮貌地請病人配合","scene":"抽血","prompt":{"en":"You are going to take a patient's temperature. Write three polite requests or instructions.","zh":"你要幫病人量體溫，寫三句有禮貌的請求或指示。","sample":"Please sit down. Could you turn your head a little? Please don't move for a few seconds."}},{"unit":26,"dialogue":[{"who":"Nurse A","en":"Do you know the man in bed 3?","zh":"你認識 3 床那位先生嗎？"},{"who":"Nurse B","en":"Yes. He is the patient who came in last night.","zh":"認識，他是昨晚入院的病人。"},{"who":"Nurse A","en":"Is this the medicine that the doctor ordered for him?","zh":"這是醫生幫他開的藥嗎？"},{"who":"Nurse B","en":"Yes. But first check the name on the wristband that he is wearing.","zh":"對，不過要先核對他戴的手圈上的名字。"},{"who":"Nurse A","en":"Who is the woman that is talking to him?","zh":"跟他說話的那位女士是誰？"},{"who":"Nurse B","en":"That is his daughter. She is the one who lives in Tainan.","zh":"那是他女兒，就是住台南的那位。"}],"questions":[{"q":"When did the patient in bed 3 come in?","options":["This morning","Last week","Last night"],"answer":2},{"q":"Who is the woman talking to him?","options":["His daughter","A doctor","His wife"],"answer":0}],"variations":[{"zh":"我喜歡那位很有耐心的老師。","en":"I like the teacher who is very patient."},{"zh":"這是我昨天買的手機。","en":"This is the phone that I bought yesterday."}],"cando":"用 who／which／that 補充說明是哪一個人或東西","scene":"交班：說清楚是哪一位病人","prompt":{"en":"Describe two people or things in your life with who, which, or that.","zh":"用 who／which／that 描述你生活中的兩個人或兩樣東西。","sample":"I have a friend who studies medicine. My favorite song is the one that my mom often sings."}},{"unit":27,"dialogue":[{"who":"Visitor","en":"Excuse me. Can you tell me where Room 512 is?","zh":"不好意思，可以告訴我 512 號房在哪裡嗎？"},{"who":"Nurse Chen","en":"Sure. It is at the end of the hall.","zh":"好的，在走廊盡頭。"},{"who":"Visitor","en":"Do you know when the doctor will come?","zh":"你知道醫生什麼時候會來嗎？"},{"who":"Nurse Chen","en":"I am not sure what time he will come. Maybe after lunch.","zh":"我不確定他幾點會來，也許午餐後。"},{"who":"Visitor","en":"Could you tell me if my mother ate breakfast?","zh":"可以告訴我，我媽媽有沒有吃早餐嗎？"},{"who":"Nurse Chen","en":"Let me check what she ate.","zh":"我查一下她吃了什麼。"}],"questions":[{"q":"Where is Room 512?","options":["Next to the elevator","On the first floor","At the end of the hall"],"answer":2},{"q":"When will the doctor maybe come?","options":["After lunch","Before lunch","Tomorrow"],"answer":0}],"variations":[{"zh":"你知道現在幾點嗎？","en":"Do you know what time it is?"},{"zh":"我不記得他住在哪裡。","en":"I don't remember where he lives."}],"cando":"用 Can you tell me…／Do you know… 有禮貌地問（後面用直述句語序）","scene":"家屬在病房問路、問狀況","prompt":{"en":"You are lost in a new hospital. Write three polite questions that start with Can you tell me… or Do you know…","zh":"你在新醫院迷路了，寫三個用 Can you tell me… 或 Do you know… 開頭的問句。","sample":"Can you tell me where the elevator is? Do you know what time the pharmacy closes? Can you tell me how I get to the emergency room?"}},{"unit":28,"dialogue":[{"who":"Nurse Chen","en":"What were you doing when you fell?","zh":"你跌倒的時候在做什麼？"},{"who":"Mr. Chen","en":"I was walking to the bathroom.","zh":"我正走去廁所。"},{"who":"Nurse Chen","en":"Were the lights on?","zh":"燈是開著的嗎？"},{"who":"Mr. Chen","en":"No. Everyone was sleeping, so I didn't turn them on.","zh":"沒有，大家都在睡覺，所以我沒開燈。"},{"who":"Nurse Chen","en":"Was anyone helping you?","zh":"有人在扶你嗎？"},{"who":"Mr. Chen","en":"No. My son was talking on the phone outside.","zh":"沒有，我兒子在外面講電話。"}],"questions":[{"q":"What was Mr. Chen doing when he fell?","options":["Sleeping","Walking to the bathroom","Talking on the phone"],"answer":1},{"q":"Why didn't he turn on the lights?","options":["The lights were broken.","He forgot.","Everyone was sleeping."],"answer":2}],"variations":[{"zh":"你打電話來的時候我正在洗澡。","en":"I was taking a shower when you called."},{"zh":"昨天這個時候他們在開會。","en":"They were having a meeting at this time yesterday."}],"cando":"用 was／were ＋ -ing 說事情發生時正在做什麼","scene":"問病人跌倒經過","prompt":{"en":"Write about what you and your family were doing at eight last night.","zh":"寫昨晚八點你和家人各自在做什麼（was／were ＋ -ing）。","sample":"At eight last night, I was studying in my room. My dad was watching TV. My sister was talking on the phone."}},{"unit":29,"dialogue":[{"who":"Nurse Chen","en":"If your fever comes back, please come back to the hospital.","zh":"如果又發燒，請回醫院。"},{"who":"Mr. Lin","en":"What if the wound hurts?","zh":"如果傷口痛呢？"},{"who":"Nurse Chen","en":"If it hurts a little, you can take this pill.","zh":"如果有一點痛，可以吃這顆藥。"},{"who":"Nurse Chen","en":"If it gets red and hot, call us right away.","zh":"如果變紅、變熱，馬上打給我們。"},{"who":"Mr. Lin","en":"Is it OK to walk every day?","zh":"我可以每天走路嗎？"},{"who":"Nurse Chen","en":"Yes, the doctor wants you to walk. If you walk a little every day, you will feel stronger.","zh":"可以，醫師希望你多走動。每天走一點，你會覺得比較有力氣。"}],"questions":[{"q":"What should Mr. Lin do if the wound gets red and hot?","options":["Walk more","Call the hospital right away","Take a pill"],"answer":1},{"q":"What does the nurse say about walking every day?","options":["The wound will hurt.","He will feel stronger.","He will get a fever."],"answer":1}],"variations":[{"zh":"如果你明天有空，我們去看電影。","en":"If you are free tomorrow, let's see a movie."},{"zh":"如果你明天很忙，我們下週再去。","en":"If you are busy tomorrow, we will go next week."}],"cando":"用 If ＋ 現在式, will／祈使句 說可能發生的情況和怎麼處理","scene":"出院衛教：什麼情況要回診","prompt":{"en":"Give a patient three if-instructions for after they go home.","zh":"給出院病人三個 if 的提醒（如果…就…）。","sample":"If you feel dizzy, sit down and rest. If the pain gets worse, call us. If you have questions about your medicine, ask your pharmacist."}},{"unit":30,"dialogue":[{"who":"Doctor","en":"How is Mrs. Chen this morning?","zh":"陳太太今天早上如何？"},{"who":"Nurse Chen","en":"She says she feels better.","zh":"她說她覺得好一點了。"},{"who":"Nurse Chen","en":"But she told me that she didn't sleep well.","zh":"但她跟我說她沒睡好。"},{"who":"Doctor","en":"Did she say why?","zh":"她有說為什麼嗎？"},{"who":"Nurse Chen","en":"She said the room was noisy.","zh":"她說房間很吵。"},{"who":"Doctor","en":"OK. Tell her that we will move her to a quiet room.","zh":"好，告訴她我們會幫她換到安靜的房間。"}],"questions":[{"q":"What did Mrs. Chen say about her sleep?","options":["She didn't sleep well.","She slept very well.","She slept all day."],"answer":0},{"q":"Why didn't she sleep well?","options":["The room was noisy.","She was in pain.","She was hungry."],"answer":0}],"variations":[{"zh":"他說他明天會來。","en":"He said he would come tomorrow."},{"zh":"她告訴我她是護理師。","en":"She told me that she was a nurse."}],"cando":"用 say／tell 轉述病人或醫生說的話","scene":"向醫師報告病人說了什麼","prompt":{"en":"Think of something a friend or teacher told you this week. Report it in three sentences with say or tell.","zh":"想一件這週朋友或老師跟你說的事，用 say／tell 轉述成三句。","sample":"My teacher said the test was next Friday. She told us to review Chapter 5. My friend says she is nervous."}},{"unit":31,"dialogue":[{"who":"Nurse Chen","en":"How long have you been coughing?","zh":"你咳嗽多久了？"},{"who":"Mrs. Wang","en":"I have been coughing for five days.","zh":"我已經咳五天了。"},{"who":"Nurse Chen","en":"Have you been taking any medicine?","zh":"你有一直在吃什麼藥嗎？"},{"who":"Mrs. Wang","en":"Yes. I have been taking cough syrup since Monday.","zh":"有，我從星期一開始吃咳嗽糖漿。"},{"who":"Nurse Chen","en":"Has your son been feeling sick too?","zh":"你兒子也一直不舒服嗎？"},{"who":"Mrs. Wang","en":"Yes. He has been sneezing all morning.","zh":"對，他打噴嚏打了一整個早上。"}],"questions":[{"q":"How long has Mrs. Wang been coughing?","options":["All morning","Five days","Since Monday"],"answer":1},{"q":"What has her son been doing all morning?","options":["Sleeping","Coughing","Sneezing"],"answer":2}],"variations":[{"zh":"我等公車等了二十分鐘了。","en":"I have been waiting for the bus for twenty minutes."},{"zh":"她從早上就一直在讀書。","en":"She has been studying since this morning."}],"cando":"用 have／has been ＋ -ing 說一個動作持續了多久（症狀持續時間）","scene":"急診問診：咳嗽、打噴嚏多久了","prompt":{"en":"Write three sentences about things you have been doing lately. Use for or since.","zh":"用三句寫你最近一直在做的事，加上 for 或 since。","sample":"I have been studying English for two months. I have been going to bed late since my exams started. I have been drinking more water since last week."}},{"unit":32,"dialogue":[{"who":"Doctor","en":"What happened before he came in?","zh":"他來之前發生了什麼事？"},{"who":"Nurse Chen","en":"He had eaten some seafood that was not fresh.","zh":"他吃了一些不新鮮的海鮮。"},{"who":"Nurse Chen","en":"By the time he arrived, he had vomited three times.","zh":"他到院的時候，已經吐了三次。"},{"who":"Doctor","en":"Had he taken any medicine?","zh":"他之前有吃藥嗎？"},{"who":"Nurse Chen","en":"Yes. His wife had given him some stomach medicine.","zh":"有，他太太先給他吃了一些胃藥。"},{"who":"Doctor","en":"OK. Let's check his blood pressure first.","zh":"好，先量他的血壓。"}],"questions":[{"q":"What had the patient eaten?","options":["Spicy noodles","Seafood that was not fresh","Cold rice"],"answer":1},{"q":"How many times had he vomited before he arrived?","options":["Twice","Three times","Once"],"answer":1}],"variations":[{"zh":"我到的時候電影已經開始了。","en":"When I arrived, the movie had already started."},{"zh":"她去日本以前從沒看過雪。","en":"She had never seen snow before she went to Japan."}],"cando":"用 had ＋ 過去分詞說過去某件事之前就已經發生的事","scene":"描述病人到院前的經過","prompt":{"en":"Write about a time you were late. Say what had already happened when you arrived.","zh":"寫一次你遲到的經驗：你到的時候，什麼事已經發生了？","sample":"I was late for class last week. When I arrived, the teacher had already started the quiz. My friends had finished the first page."}},{"unit":33,"dialogue":[{"who":"Ben","en":"If you had a free year, what would you do?","zh":"如果你有一整年空閒，你會做什麼？"},{"who":"Amy","en":"I would work as a nurse in the US.","zh":"我會去美國當護理師。"},{"who":"Ben","en":"Really? If I were you, I would travel first.","zh":"真的？如果我是你，我會先去旅行。"},{"who":"Amy","en":"If my English were better, I would go next year.","zh":"如果我英文更好，我明年就去。"},{"who":"Ben","en":"Then you should practice every day.","zh":"那你應該每天練習。"},{"who":"Amy","en":"I know. If I had more time, I would practice more.","zh":"我知道。如果我有更多時間，我會練更多。"}],"questions":[{"q":"What would Amy do with a free year?","options":["Study medicine","Work as a nurse in the US","Travel around Asia"],"answer":1},{"q":"What would Ben do first?","options":["Study English","Travel","Work"],"answer":1}],"variations":[{"zh":"如果我有車，我會載你回家。","en":"If I had a car, I would drive you home."},{"zh":"如果我是他，我會去看醫生。","en":"If I were him, I would see a doctor."}],"cando":"用 If ＋ 過去式, would ＋ 原形說跟事實相反的假設、給建議","scene":"同學聊「如果…會怎樣」","prompt":{"en":"If you could work in any country, where would you work and why? Write three sentences.","zh":"如果你可以在任何國家工作，你會去哪裡？為什麼？寫三句。","sample":"If I could work in any country, I would work in the US. I would learn a lot there. If I lived there, my English would get better."}},{"unit":34,"dialogue":[{"who":"Nurse Chen","en":"This medicine should be taken with food.","zh":"這個藥應該跟食物一起吃。"},{"who":"Mr. Lin","en":"Can it be taken at night?","zh":"可以晚上吃嗎？"},{"who":"Nurse Chen","en":"Yes, it can. But it must not be taken with alcohol.","zh":"可以，但不能跟酒一起吃。"},{"who":"Mr. Lin","en":"What about my wound?","zh":"那我的傷口呢？"},{"who":"Nurse Chen","en":"It must be kept clean. The dressing should be changed every day.","zh":"傷口必須保持乾淨，紗布應該每天換。"},{"who":"Mr. Lin","en":"Will the stitches be removed next week?","zh":"縫線下週會拆嗎？"},{"who":"Nurse Chen","en":"Yes. They will be removed on Monday.","zh":"會，星期一拆。"}],"questions":[{"q":"How should the medicine be taken?","options":["With alcohol","Only before bed","With food"],"answer":2},{"q":"When will the stitches be removed?","options":["In two weeks","On Monday","Tomorrow"],"answer":1}],"variations":[{"zh":"這份表格必須今天交。","en":"This form must be handed in today."},{"zh":"這個問題可以很快解決。","en":"This problem can be solved quickly."}],"cando":"用 must／should／can ＋ be ＋ 過去分詞說處置規定（給藥、傷口照護）","scene":"給藥和傷口照護說明","prompt":{"en":"Write three rules for your classroom or a hospital ward with must be, should be, or can't be.","zh":"用 must be／should be／can't be 寫三條教室或病房的規定。","sample":"Phones must be turned off in class. The floor should be cleaned every night. Food can't be eaten in the lab."}},{"unit":35,"dialogue":[{"who":"Daughter","en":"Do you think my father is getting better?","zh":"你覺得我爸爸有好轉嗎？"},{"who":"Nurse Chen","en":"Yes. I think the new medicine is working.","zh":"有，我覺得新的藥有效。"},{"who":"Daughter","en":"I hope he can go home soon.","zh":"我希望他能早點回家。"},{"who":"Nurse Chen","en":"I'm sure he wants to go home too.","zh":"我相信他也很想回家。"},{"who":"Nurse Chen","en":"But it is important that he finishes all the antibiotics.","zh":"不過，他把抗生素吃完很重要。"},{"who":"Daughter","en":"I understand. I'm glad that he has a good nurse.","zh":"我了解。我很高興他有一位好護理師。"}],"questions":[{"q":"What does the nurse think?","options":["He needs surgery.","He should go home today.","The new medicine is working."],"answer":2},{"q":"What is important, according to the nurse?","options":["He finishes all the antibiotics.","He eats more.","He walks every day."],"answer":0}],"variations":[{"zh":"我覺得這個考試很難。","en":"I think this test is difficult."},{"zh":"我希望明天是晴天。","en":"I hope it will be sunny tomorrow."}],"cando":"用 I think／I hope／I'm sure (that)… 說看法和希望","scene":"家屬會談","prompt":{"en":"Write three sentences about your future with I think…, I hope…, and I'm sure…","zh":"用 I think…、I hope…、I'm sure… 寫三句關於你未來的話。","sample":"I think nursing is a good job for me. I hope I can pass the NCLEX. I'm sure my family will support me."}},{"unit":36,"dialogue":[{"who":"Nurse A","en":"The woman sitting by the window is Mrs. Lin.","zh":"坐在窗邊的那位女士是林太太。"},{"who":"Nurse B","en":"Is she the patient admitted this morning?","zh":"她是今天早上入院的病人嗎？"},{"who":"Nurse A","en":"Yes. The man wearing a blue shirt is her husband.","zh":"對，穿藍色襯衫的男士是她先生。"},{"who":"Nurse B","en":"What about the boy crying in bed 4?","zh":"那 4 床在哭的男孩呢？"},{"who":"Nurse A","en":"He is scared. The X-ray ordered by the doctor is at two.","zh":"他很害怕。醫生開的 X 光排在兩點。"},{"who":"Nurse B","en":"OK. I will bring him a toy.","zh":"好，我拿個玩具給他。"}],"questions":[{"q":"Who is the man wearing a blue shirt?","options":["Mrs. Lin's husband","A doctor","The boy's father"],"answer":0},{"q":"When is the boy's X-ray?","options":["At two","This morning","At ten"],"answer":0}],"variations":[{"zh":"那個在打籃球的男生是我弟弟。","en":"The boy playing basketball is my brother."},{"zh":"這是一本用簡單英文寫的書。","en":"This is a book written in simple English."}],"cando":"用 -ing／過去分詞片語接在名詞後面，說清楚是哪一位","scene":"交班時指認病人","prompt":{"en":"Describe three people or things in a place you know. Use -ing phrases (\\"the man standing…\\", \\"the girl wearing…\\") in two sentences and a past participle phrase (\\"a book written in English\\", \\"the medicine kept in the fridge\\") in one.","zh":"描述一個場景裡的三個人或東西：兩句用 -ing 片語（the man standing…、the girl wearing…），一句用過去分詞片語（a book written in English、the medicine kept in the fridge）。","sample":"The man standing at the door is a security guard. The girl wearing a pink coat is waiting for her mom. The medicine kept in the fridge is for the patient in Bed 5."}},{"unit":37,"dialogue":[{"who":"Doctor","en":"How is Mr. Wu today?","zh":"吳先生今天如何？"},{"who":"Nurse Chen","en":"Although his fever is gone, he still feels weak.","zh":"雖然他退燒了，但還是覺得很虛弱。"},{"who":"Doctor","en":"Is he eating?","zh":"他有吃東西嗎？"},{"who":"Nurse Chen","en":"Yes. Despite his sore throat, he ate half of his lunch.","zh":"有。儘管喉嚨痛，他還是吃了一半的午餐。"},{"who":"Nurse Chen","en":"His blood pressure is normal. However, his heart rate is a little fast.","zh":"他的血壓正常，不過心跳有點快。"},{"who":"Doctor","en":"OK. Let's check it again in an hour.","zh":"好，一小時後再量一次。"}],"questions":[{"q":"How does Mr. Wu feel?","options":["Hungry","Hot","Weak"],"answer":2},{"q":"What is the problem with his vital signs?","options":["His heart rate is a little fast.","His blood pressure is high.","He has a fever."],"answer":0}],"variations":[{"zh":"雖然很累，她還是去上班了。","en":"Although she was tired, she still went to work."},{"zh":"儘管下雨，比賽還是照常進行。","en":"Despite the rain, the game went on."}],"cando":"用 although／despite／however 說出兩件相反的事","scene":"跟醫師報告病人狀況","prompt":{"en":"Write two contrasts about yourself: one with although (in one sentence), and one with however (two short sentences, the second starting with However).","zh":"寫你身上兩組相反的事：一組用 although（一句寫完）；一組用 however（先寫一句，下一句用 However 開頭說相反的事）。","sample":"Although English is hard for me, I practice every day. I love nursing. However, night shifts are tiring."}},{"unit":38,"dialogue":[{"who":"Nurse A","en":"Why was Mrs. Ho's surgery delayed?","zh":"何太太的手術為什麼延後？"},{"who":"Nurse B","en":"It was delayed due to a high fever.","zh":"因為高燒延後了。"},{"who":"Nurse A","en":"Was her blood sugar high because of the fever?","zh":"她的血糖高是因為發燒嗎？"},{"who":"Nurse B","en":"Partly. She also skipped her insulin. As a result, her blood sugar went up.","zh":"部分是。她也漏打了胰島素，結果血糖就升高了。"},{"who":"Nurse A","en":"So she needs more teaching.","zh":"所以她需要更多衛教。"},{"who":"Nurse B","en":"Yes. Therefore, I will teach her again tomorrow.","zh":"對，因此我明天會再教她一次。"}],"questions":[{"q":"Why was the surgery delayed?","options":["Because of low blood sugar","Because the doctor was late","Because of a high fever"],"answer":2},{"q":"What did Mrs. Ho skip?","options":["Her blood test","Her lunch","Her insulin"],"answer":2}],"variations":[{"zh":"因為交通的關係，我們遲到了。","en":"We were late because of the traffic."},{"zh":"他沒睡覺，因此他今天很累。","en":"He did not sleep. Therefore, he is very tired today."}],"cando":"用 because of／due to／therefore／as a result 寫因果（報告用語）","scene":"討論手術延後的原因","prompt":{"en":"Write two sentences about a cause and its result in your life. Use because of or due to, and therefore or as a result.","zh":"寫兩句你生活中的因果，用 because of／due to 和 therefore／as a result。","sample":"I missed the bus because of the heavy rain. As a result, I was late for my first class."}},{"unit":39,"dialogue":[{"who":"Nurse A","en":"Let's look at Mr. Lee's chart.","zh":"我們看一下李先生的紀錄。"},{"who":"Nurse B","en":"His temperature rose from 37 to 39 degrees Celsius last night.","zh":"他的體溫昨晚從攝氏 37 度升到 39 度。"},{"who":"Nurse A","en":"What about this morning?","zh":"那今天早上呢？"},{"who":"Nurse B","en":"After the medicine, it dropped to 37.5.","zh":"吃藥以後降到 37.5 度。"},{"who":"Nurse A","en":"And his heart rate?","zh":"那心跳呢？"},{"who":"Nurse B","en":"It remained stable at about 80.","zh":"一直維持在 80 左右。"}],"questions":[{"q":"How high did Mr. Lee's temperature go?","options":["38 degrees","37.5 degrees","39 degrees"],"answer":2},{"q":"What happened to his heart rate?","options":["It went up.","It dropped.","It remained stable."],"answer":2}],"variations":[{"zh":"學生人數從 50 人增加到 80 人。","en":"The number of students increased from 50 to 80."},{"zh":"價格去年維持不變。","en":"The price remained the same last year."}],"cando":"用 rise／drop／remain stable ＋ from…to… 描述圖表和數字的變化","scene":"看體溫和心跳的紀錄","prompt":{"en":"Describe the chart in three or four sentences: where it starts, how it changes, and where it ends. Use the numbers.","zh":"用三到四句描述這張圖：一開始多少、怎麼變化、最後多少（要寫出數字）。","sample":"On Monday, her systolic blood pressure was 150 mmHg. It dropped to 130 on Wednesday. Then it remained stable for one day. On Friday, it was 128.","chart":{"title":"Mrs. Chen's systolic blood pressure (mmHg)","points":[{"label":"Mon","value":150},{"label":"Tue","value":142},{"label":"Wed","value":130},{"label":"Thu","value":130},{"label":"Fri","value":128}]}}},{"unit":40,"dialogue":[{"who":"Examiner","en":"Do you think nurses need to speak English well?","zh":"你覺得護理師需要很會說英文嗎？"},{"who":"Amy","en":"Yes, I think so. In my opinion, English is very important for nurses.","zh":"是的。我認為英文對護理師非常重要。"},{"who":"Amy","en":"The main reason is that many patients are from other countries.","zh":"主要原因是很多病人來自其他國家。"},{"who":"Amy","en":"For example, last month I met a patient from Vietnam.","zh":"例如，上個月我遇到一位越南來的病人。"},{"who":"Amy","en":"We spoke English, so I could explain her medicine to her.","zh":"我們用英文溝通，所以我能跟她解釋她的藥。"},{"who":"Examiner","en":"Thank you. That is a clear answer.","zh":"謝謝，回答得很清楚。"}],"questions":[{"q":"What is Amy's opinion?","options":["English is too hard to learn.","Nurses don't need English.","English is very important for nurses."],"answer":2},{"q":"What example does Amy give?","options":["An English test","A trip to the US","A patient from Vietnam"],"answer":2}],"variations":[{"zh":"在我看來，睡眠比讀書更重要。","en":"In my opinion, sleep is more important than studying."},{"zh":"舉例來說，我每天花一個小時通勤。","en":"For example, I spend an hour commuting every day."}],"cando":"用「意見 → 理由 → 例子 → 結論」把口說回答講長","scene":"口說測驗練習","prompt":{"en":"Question: Should students have part-time jobs? Answer in four sentences: your opinion, a reason, an example, and a conclusion.","zh":"題目：學生應該打工嗎？用四句回答：意見、理由、例子、結論。","sample":"I think students can have part-time jobs. The main reason is that they learn to manage money. For example, my friend works at a café and saves money every month. So, a part-time job can be good if it does not hurt your grades.","scaffold":["I think…","The main reason is that…","For example, …","So, …"]}},{"unit":41,"dialogue":[{"who":"Nurse Chen","en":"Sleep is important for your health.","zh":"睡眠對你的健康很重要。"},{"who":"Mr. Lin","en":"I know, but I have a cold, and I can't sleep.","zh":"我知道，但我感冒了，睡不著。"},{"who":"Nurse Chen","en":"Do you have diabetes too?","zh":"你也有糖尿病嗎？"},{"who":"Mr. Lin","en":"Yes. The doctor gave me a new medicine for it.","zh":"有，醫生給了我一種治療它的新藥。"},{"who":"Nurse Chen","en":"The medicine on your table? Take it after breakfast.","zh":"是你桌上那個藥嗎？早餐後吃。"},{"who":"Mr. Lin","en":"OK. Vegetables are good for people with diabetes, right?","zh":"好。蔬菜對糖尿病患者很好，對吧？"}],"questions":[{"q":"Why can't Mr. Lin sleep?","options":["He has a cold.","The room is noisy.","He has diabetes."],"answer":0},{"q":"When should he take the new medicine?","options":["After breakfast","Before bed","Before lunch"],"answer":0}],"variations":[{"zh":"咖啡讓我睡不著。","en":"Coffee keeps me awake."},{"zh":"冰箱裡的牛奶過期了。","en":"The milk in the fridge has expired."}],"cando":"泛指不加冠詞，特指才用 the；說得出疾病名稱的冠詞","scene":"衛教：講健康觀念","prompt":{"en":"Write three health tips about things in general, with no \\"the\\" — for example, Water…, Vegetables…, Exercise…","zh":"寫三個健康小建議，用泛指的說法、不加 the，例如 Water…、Vegetables…、Exercise…","sample":"Water is good for your skin. Vegetables give you vitamins. Exercise helps you sleep better."}},{"unit":42,"dialogue":[{"who":"Amy","en":"Hi, I'd like to make an appointment with Dr. Lin.","zh":"你好，我想跟林醫師預約。"},{"who":"Clinic","en":"Sure. What's the problem?","zh":"好的，哪裡不舒服？"},{"who":"Amy","en":"I came down with the flu, and I haven't gotten over it yet.","zh":"我得了流感，到現在還沒好。"},{"who":"Clinic","en":"How about tomorrow at ten?","zh":"明天十點可以嗎？"},{"who":"Amy","en":"Great. I also need to take a day off and look after my son.","zh":"好。我也要請一天假照顧我兒子。"},{"who":"Clinic","en":"OK. Please fill out a form when you arrive.","zh":"好的，到的時候請先填一張表。"}],"questions":[{"q":"What is wrong with Amy?","options":["She has the flu.","She needs a checkup.","She hurt her back."],"answer":0},{"q":"What does Amy need to take tomorrow?","options":["A test","A bus","A day off"],"answer":2}],"variations":[{"zh":"你可以幫我照顧我的貓嗎？","en":"Can you look after my cat?"},{"zh":"請填寫這張表格。","en":"Please fill out this form."}],"cando":"用整組搭配和片語動詞（make an appointment、take off、look after）說得更自然","scene":"打電話預約和請假","prompt":{"en":"Write a short message to your teacher: you are sick and need to take a day off. Use two phrases from this unit.","zh":"寫一則簡短訊息給老師：你生病了要請假，用到兩個這單元的片語。","sample":"Hi, Ms. Chen. I came down with a cold, so I need to take a day off today. I will make an appointment with a doctor. I will catch up on the homework tomorrow."}},{"unit":43,"dialogue":[{"who":"Mia","en":"How was the night shift?","zh":"夜班還好嗎？"},{"who":"Ken","en":"Busy. Mr. Lee fell while he was walking to the bathroom.","zh":"很忙。李先生走去廁所的時候跌倒了。"},{"who":"Mia","en":"Oh no! Was he hurt?","zh":"天啊！他有受傷嗎？"},{"who":"Ken","en":"Not badly. When I got there, he had already stood up by himself.","zh":"不嚴重。我到的時候，他已經自己站起來了。"},{"who":"Mia","en":"He used to be very careful.","zh":"他以前很小心的。"},{"who":"Ken","en":"I know. He had taken a sleeping pill, so he was a little dizzy.","zh":"我知道。他吃了安眠藥，所以有點頭暈。"}],"questions":[{"q":"What happened to Mr. Lee?","options":["He fell on the way to the bathroom.","He forgot his medicine.","He woke up at five."],"answer":0},{"q":"Why was he dizzy?","options":["He had not eaten dinner.","He had taken a sleeping pill.","He had walked too fast."],"answer":1}],"variations":[{"zh":"我到的時候，會議已經開始了。","en":"When I arrived, the meeting had already started.","alt":["When I got there, the meeting had already started.","The meeting had already started when I arrived."]},{"zh":"她以前每天早上都跑步。","en":"She used to run every morning.","alt":["She used to go running every morning.","She used to jog every morning."]}],"cando":"用過去式、過去進行式、過去完成式和 used to 把一件事的先後講清楚","scene":"交班時說昨晚發生的事","prompt":{"en":"Write four sentences about something that happened to you or a friend. Use the past simple, the past continuous (was/were + -ing), the past perfect (had + past participle) and used to — one in each sentence.","zh":"寫四句，說一件你或朋友身上發生過的事：過去式、過去進行式、過去完成式和 used to 各用一次。","sample":"I used to ride my scooter to school. Last winter, I was riding home in the rain when I slipped. When my friend arrived, I had already called my mom. Luckily, I only hurt my knee."}},{"unit":44,"dialogue":[{"who":"Mia","en":"Are you working on Friday?","zh":"你週五有上班嗎？"},{"who":"Ken","en":"No, I'm taking the GEPT on Friday morning.","zh":"沒有，我週五早上要考全民英檢。"},{"who":"Mia","en":"Good luck! This time next week, you'll be sitting in the exam room.","zh":"加油！下週這個時候，你就會坐在考場裡了。"},{"who":"Ken","en":"I know. By then, I'll have reviewed all the units.","zh":"對啊。到時候，我就會把所有單元都複習完了。"},{"who":"Mia","en":"Will you have finished the writing practice too?","zh":"寫作練習你也會寫完嗎？"},{"who":"Ken","en":"I hope so. I'm meeting my tutor on Wednesday to check it.","zh":"希望會。我週三要跟家教見面，請他幫我看。"}],"questions":[{"q":"Why isn't Ken working on Friday?","options":["He is taking an exam.","He is meeting his tutor.","He is sick."],"answer":0},{"q":"When is Ken meeting his tutor?","options":["On Monday","On Wednesday","On Friday"],"answer":1}],"variations":[{"zh":"我週六要跟朋友吃晚餐。","en":"I'm having dinner with my friends on Saturday.","alt":["I'm having dinner with friends on Saturday.","I am having dinner with my friends on Saturday.","I'm going to have dinner with my friends on Saturday."]},{"zh":"到了十點，我就會寫完報告了。","en":"By ten o'clock, I'll have finished the report.","alt":["By 10 o'clock, I will have finished the report.","I'll have finished the report by ten.","By ten, I'll have finished the report."]}],"cando":"說清楚未來的安排、某個時間正在做的事，以及在那之前會完成什麼","scene":"安排下週的班表和考試","prompt":{"en":"Write four sentences about next week: one arrangement you have made (present continuous), what you will be doing at a certain time (will be + -ing), and two things you will have finished by the end of the week (will have + past participle).","zh":"寫四句，說你下週的計畫：一個已經約好的安排（現在進行式）、某個時間你會正在做什麼（will be + -ing），還有兩件週末前會完成的事（will have + 過去分詞）。","sample":"I'm meeting my study group on Monday evening. At nine on Wednesday morning, I'll be taking a pharmacology quiz. By Friday, I'll have finished my care plan. I'll also have learned sixty new words by the end of the week."}},{"unit":45,"dialogue":[{"who":"Ken","en":"Mrs. Chen didn't touch her lunch.","zh":"陳太太午餐都沒動。"},{"who":"Mia","en":"She must be feeling sick. Did she have a fever?","zh":"她一定是不舒服。她有發燒嗎？"},{"who":"Ken","en":"No, her temperature was normal. She might be worried about her surgery.","zh":"沒有，體溫正常。她可能在擔心手術。"},{"who":"Mia","en":"That could be it. Her daughter didn't come this morning.","zh":"有可能。她女兒今天早上沒來。"},{"who":"Ken","en":"Her daughter must have been busy. She usually visits every day.","zh":"她女兒一定是在忙。她平常每天都會來。"},{"who":"Mia","en":"Let's talk to Mrs. Chen. She might not have slept well last night either.","zh":"我們去跟陳太太聊聊。她昨晚可能也沒睡好。"}],"questions":[{"q":"Why do the nurses think something is wrong?","options":["Mrs. Chen didn't eat her lunch.","Mrs. Chen had a fever.","Mrs. Chen fell down."],"answer":0},{"q":"What does Ken say about Mrs. Chen's daughter?","options":["She must have been busy.","She can't have known.","She visits once a week."],"answer":0}],"variations":[{"zh":"他一定是走錯路了。","en":"He must have gone the wrong way.","alt":["He must have taken the wrong way.","He must have taken a wrong turn.","He must have taken the wrong road."]},{"zh":"她不可能在家，她的車不在。","en":"She can't be at home. Her car isn't there.","alt":["She can't be home. Her car isn't there.","She can't be at home because her car isn't there.","She cannot be at home. Her car is not there."]}],"cando":"根據線索推測現在和過去的事，分清楚確定、可能和不可能","scene":"照顧病人時根據線索推測","prompt":{"en":"Look at the clues and write four guesses: a patient's bed is empty, his slippers are gone, and the bathroom light is on. Use must, might and can't — two guesses about now and two about the past (must/might/can't have + past participle).","zh":"看線索寫四句推測：病人的床是空的、拖鞋不見了、廁所的燈亮著。用 must、might、can't：兩句推測現在，兩句推測過去（must／might／can't have + 過去分詞）。","sample":"He must be in the bathroom. He might need help getting back to bed. He must have woken up before breakfast. He can't have left the ward, because his shoes are still under the bed."}},{"unit":46,"dialogue":[{"who":"Mia","en":"I almost gave Mr. Wu the wrong medicine today.","zh":"我今天差點給吳先生錯的藥。"},{"who":"Ken","en":"What happened?","zh":"怎麼了？"},{"who":"Mia","en":"Two patients had the same last name. If I hadn't checked his wristband, I would have made a mistake.","zh":"有兩個病人同姓。如果我沒有核對他的手圈，我就會出錯了。"},{"who":"Ken","en":"Good thing you checked. If you had given it, he might have had a reaction.","zh":"還好你有核對。如果你給了，他可能會出現不良反應。"},{"who":"Mia","en":"I know. If I had been more tired, I might have missed it.","zh":"對啊。如果我當時更累，可能就沒發現了。"},{"who":"Ken","en":"That's why we always check two identifiers.","zh":"所以我們一定要核對兩種身分資料。"}],"questions":[{"q":"Why did Mia almost make a mistake?","options":["Two patients had the same last name.","She forgot her wristband.","The medicine was new."],"answer":0},{"q":"What stopped the mistake?","options":["Mia asked a doctor.","Mia checked the wristband.","Mr. Wu said no."],"answer":1}],"variations":[{"zh":"如果我有帶傘，我就不會淋濕了。","en":"If I had brought an umbrella, I wouldn't have gotten wet.","alt":["If I had brought an umbrella, I wouldn't have got wet.","If I'd brought an umbrella, I wouldn't have gotten wet.","If I had taken an umbrella, I wouldn't have gotten wet."]},{"zh":"如果她早點睡，她就不會遲到了。","en":"If she had gone to bed earlier, she wouldn't have been late.","alt":["If she had slept earlier, she wouldn't have been late.","If she'd gone to bed earlier, she wouldn't have been late."]}],"cando":"說出「當初如果…，結果就會…」，談過去的後悔和教訓","scene":"檢討一次差點出錯的事","prompt":{"en":"Think of a time something went wrong. Write four sentences: what happened, and three 'If I had…, I would/wouldn't have…' sentences about what could have been different.","zh":"想一次出錯的經驗。寫四句：發生了什麼事，再用三句「If I had…, I would／wouldn't have…」說當初如果不一樣，結果會怎樣。","sample":"Last month I missed my train to Taichung. If I had checked the time, I wouldn't have missed it. If I had left home earlier, I would have caught it easily. If I hadn't missed it, I would have arrived at class on time."}},{"unit":47,"dialogue":[{"who":"Ken","en":"I wish I had more time to practice English.","zh":"我希望我有更多時間練英文。"},{"who":"Mia","en":"Me too. I wish I had started earlier.","zh":"我也是。真希望我早點開始。"},{"who":"Ken","en":"Yesterday I stayed up late. I shouldn't have done that.","zh":"昨天我熬夜了。我不應該那樣做的。"},{"who":"Mia","en":"You should have gone to bed. You have an early shift today.","zh":"你應該去睡覺的。你今天上早班。"},{"who":"Ken","en":"If only I could sleep for one more hour!","zh":"要是我能再睡一個小時就好了！"},{"who":"Mia","en":"Next time, put your phone away at eleven.","zh":"下次十一點就把手機收起來吧。"}],"questions":[{"q":"What does Ken regret?","options":["Staying up late","Missing his shift","Forgetting his phone"],"answer":0},{"q":"What does Mia wish?","options":["She had started earlier.","She had more money.","She could change her shift."],"answer":0}],"variations":[{"zh":"我希望我不用上夜班。","en":"I wish I didn't have to work night shifts.","alt":["I wish I didn't have to work the night shift.","If only I didn't have to work night shifts."]},{"zh":"你不應該跳過早餐的。","en":"You shouldn't have skipped breakfast.","alt":["You should not have skipped breakfast."]}],"cando":"說出現在的願望和對過去的遺憾，用 should have 檢討做錯的事","scene":"下班後聊願望和遺憾","prompt":{"en":"Write four sentences: two wishes about your life now (I wish / If only + past tense) and two regrets about the past (I wish I had… / I should have…).","zh":"寫四句：兩句現在的願望（I wish／If only + 過去式），兩句對過去的遺憾（I wish I had… 或 I should have…）。","sample":"I wish I had more free time. If only my English were better. I wish I had started learning English earlier. I should have practiced speaking more last year."}},{"unit":48,"dialogue":[{"who":"Mia","en":"This is Mr. Wang, who came in last night.","zh":"這是王先生，他昨晚住進來的。"},{"who":"Ken","en":"Oh, Mr. Wang, whose daughter works here?","zh":"喔，就是女兒在這裡上班的王先生？"},{"who":"Mia","en":"Yes. He's in Room 12, which is next to the nurses' station.","zh":"對。他在 12 號房，就在護理站旁邊。"},{"who":"Ken","en":"OK. His blood pressure was high this morning, which worried the doctor.","zh":"好。他今天早上血壓偏高，這讓醫生有點擔心。"},{"who":"Mia","en":"He used to work in Kaohsiung, where he was a bus driver.","zh":"他以前在高雄工作，在那裡當公車司機。"},{"who":"Ken","en":"I'll check on him after lunch.","zh":"我午餐後去看看他。"}],"questions":[{"q":"Where is Mr. Wang's room?","options":["Next to the nurses' station","Near the elevator","On the third floor"],"answer":0},{"q":"What worried the doctor?","options":["His high blood pressure","His daughter","His old job"],"answer":0}],"variations":[{"zh":"我的老師是美國人，她教寫作。","en":"My teacher, who is American, teaches writing.","alt":["My teacher, who is from America, teaches writing.","My teacher, who is from the US, teaches writing."]},{"zh":"他忘了帶鑰匙，這讓他很生氣。","en":"He forgot his keys, which made him angry.","alt":["He forgot to bring his keys, which made him angry.","He forgot his keys, which made him very angry."]}],"cando":"用逗號加 who／which／whose／where 補充說明，把資訊整合成一句","scene":"介紹病房裡的人和地方","prompt":{"en":"Write four sentences about people and places in your life. Use who, which, whose and where with commas — one in each sentence.","zh":"寫四句介紹你生活裡的人和地方：用逗號加 who、which、whose、where，每句用一個。","sample":"My best friend, who studies nursing with me, lives in Taichung. Our school library, which opens at eight, is my favorite place to study. My neighbor, whose dog barks every night, is very friendly. Tainan, where my grandparents live, has the best food in Taiwan."}}]`);export{e as default};
